 "content": "from collections import Counter, deque


def transform(grid):
    """Remove singleton speckles by extending nearby non-background objects."""
    h, w = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    components = []

    # Find every monochromatic 4-connected component.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            components.append((color, cells))

    # A singleton special-color mark is noise. If it touches a larger object
    # diagonally, it belongs to that object's color; otherwise it is background.
    for color, cells in components:
        if len(cells) != 1:
            continue
        r, c = cells[0]
        adjacent_objects = []
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                if not (dy or dx):
                    continue
                y, x = r + dy, c + dx
                if not (0 <= y < h and 0 <= x < w):
                    continue
                value = grid[y][x]
                if value == background or value == color:
                    continue
                # Exclude other singleton noise marks; only established shapes
                # can determine the color hidden by a speck.
                if any(v == value and len(obj) > 1 and (y, x) in obj for v, obj in components):
                    adjacent_objects.append(value)
        if adjacent_objects:
            out[r][c] = Counter(adjacent_objects).most_common(1)[0][0]
        else:
            out[r][c] = background
    return out


